use super::*;

/// A short position, with the price that ends it at the top.
///
/// The call price leads because it decides the outcome: a short does not end when you are proved
/// right or wrong, it ends when the broker closes it. And the unreachable rows of the ladder are
/// PRINTED, marked, rather than trimmed — seeing that a 30% rise is past your exit is the point.
pub fn render_short(cap: &short::Capacity, shares: i64, rows: &[short::Outcome], compare: &[short::Exposure], carry: &short::Carry) -> String {
    let mut out = String::new();
    let m = |x: i64| crate::money::format_minor(x);
    out.push_str(&format!(
        "shorting {shares} share(s) at {} against {} of equity\n\n",
        m(cap.price.minor),
        m(cap.equity.minor)
    ));
    out.push_str(&format!(
        "  MARGIN CALL AT {}  — a rise of {:.1}% ends the position, whether or not you were right\n",
        m(cap.margin_call_price.minor),
        cap.headroom * 100.0
    ));
    out.push_str(&format!("  Regulation T allows at most {} shares ({}) on this equity\n", cap.max_shares, m(cap.max_position.minor)));
    if carry.borrow_apr > 0.0 || carry.days_held > 0 {
        out.push_str(&format!("  carry: {:.1}% borrow over {} day(s){}\n", carry.borrow_apr * 100.0, carry.days_held,
            if carry.dividends_per_share.minor > 0 { format!(", plus {} a share in dividends you owe", m(carry.dividends_per_share.minor)) } else { String::new() }));
    }

    out.push_str("\n  move      price        gross      carry          net    on equity\n");
    for o in rows {
        out.push_str(&format!(
            "  {:>+5.0}% {:>10} {:>12} {:>10} {:>12} {:>10.1}%  {}\n",
            o.move_pct * 100.0,
            m(o.at_price.minor),
            m(o.gross.minor),
            m(-(o.borrow_cost.minor + o.dividends_owed.minor)),
            m(o.net.minor),
            o.return_on_equity * 100.0,
            if o.reachable { "" } else { "PAST THE CALL — you are already out" }
        ));
    }

    if !compare.is_empty() {
        out.push_str("\n  the same view, three ways:\n");
        out.push_str("    vehicle          at risk       max loss      max gain   margin\n");
        for e in compare {
            out.push_str(&format!(
                "    {:<14}{:>12}{:>15}{:>14}{:>9}\n",
                e.vehicle.label(),
                m(e.capital_at_risk.minor),
                // ABSENT, not a big number — the price has no ceiling and a figure here would
                // invite somebody to size against it.
                e.max_loss.map(|l| m(l.minor)).unwrap_or_else(|| "UNBOUNDED".into()),
                m(e.max_gain.minor),
                if e.needs_margin { "yes" } else { "no" }
            ));
            out.push_str(&format!("      {}\n", e.note));
        }
    }

    if !cap.notes.is_empty() {
        out.push_str("\nWhat this is standing on:\n");
        for n in &cap.notes {
            out.push_str(&format!("  · {n}\n"));
        }
    }
    out
}
